head.script:
scwin.key_isur_cd = frame.opener.gIsurCd;
scwin.key_chrg_tp_cd = frame.opener.gChrgTpCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30663.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Grid_OnLoadCompleted
 * @description dts_Grid 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    try {
        // if (rowcount > 0)
        //    grd_List.AutoResizeAllCol(true);
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        // alert(rowcount);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30663.dts_Grid_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Grid_OnLoadError
 * @description dts_Grid 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Grid_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Grid);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30663.dts_Grid_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF30663.xml", SCREN_PROCS_TP_CD_07, '');
        $c.data.downloadGridViewExcel(grd_List, {fileName: "정보등록현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30663.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        if (colid === 'DETAIL') {
            await scwin.openDetailInfo(dts_Grid.getCellData(row, "ISUR_CD"), dts_Grid.getCellData(row, "CHRG_TP_CD"), dts_Grid.getCellData(row, "SEQ"), dts_Grid.getCellData(row, "DISCLS_BZ_CHRG_ASSGN_DD"));
        } else if (colid === 'REMK') {
            const acpt_no = dts_Grid.getCellData(row, "ACPT_NO");
            if (acpt_no !== '') {
                await $c.stf.openDisclViewer(dts_Grid.getCellData(row, "ACPT_NO"), "R"); // (정정)공시일 컬럼 더블클릭시 관련 보고서 뷰잉

            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30663.grd_List_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&ISUR_CD=" + scwin.key_isur_cd;
    url += "&CHRG_TP_CD=" + scwin.key_chrg_tp_cd;
    url += "&SCREN_ID=" + "ULDSTF30663.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name openDetailInfo
 * @description open Detail Info 처리
 * @param {*} isur_cd isur_cd
 * @param {*} chrg_tp_cd chrg_tp_cd
 * @param {*} seq seq
 * @param {*} assgn_dd assgn_dd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailInfo = async function(isur_cd, chrg_tp_cd, seq, assgn_dd) {
    scwin.key_isur_cd = isur_cd;
    scwin.key_chrg_tp_cd = chrg_tp_cd;
    key_seq = seq;
    key_assgn_dd = assgn_dd;
    await $c.frame.CreateFrame("child01", "/issueinfo/ULDSTF30615.gfm", "상세보기", 10, 10, 770, 610, "window", 0, 0, true);
};
